// Trainee profiles (postdocs, graduate students, SRAs). The intake form also
// offers Project Scientist (listed as postdoc) and Medical Student (listed as
// grad); see ROLE_CHOICES in scripts/trainees/fields.mjs.
//
// app/data/trainees.json is GENERATED by scripts/sync-trainees.mjs from the
// approved rows of the trainee intake Google Sheet. Do not edit it by hand:
// the next sync will overwrite it. To change a profile, edit the Sheet (or ask
// the trainee to edit their form response) and re-run the sync.
import data from './trainees.json';
import { labBySlug } from './labs.js';

export const ROLES = [
  { key: 'postdoc', label: 'Postdoctoral Scholars', singular: 'Postdoctoral Scholar' },
  { key: 'grad', label: 'Graduate Students', singular: 'Graduate Student' },
  { key: 'sra', label: 'Staff Research Associates', singular: 'Staff Research Associate' },
];
export const roleByKey = Object.fromEntries(ROLES.map((r) => [r.key, r]));

const todayIso = () => new Date().toISOString().slice(0, 10);

// A trainee is shown from their start date until their end date (inclusive).
// Pages that list trainees revalidate daily, so people drop off automatically.
export function isActive(t, today = todayIso()) {
  if (t.startDate && t.startDate > today) return false;
  if (t.endDate && t.endDate < today) return false;
  return true;
}

// Adds the lab's display name so client components don't need the lab list.
const withLab = (t) => ({ ...t, labName: labBySlug[t.lab]?.labName ?? null });

export function activeTrainees(today = todayIso()) {
  return data.trainees
    .filter((t) => isActive(t, today) && labBySlug[t.lab])
    .map(withLab)
    .sort((a, b) => a.sortName.localeCompare(b.sortName));
}

export const traineesForLab = (labSlug, today = todayIso()) =>
  activeTrainees(today).filter((t) => t.lab === labSlug);

export const traineeBySlug = (slug) => data.trainees.find((t) => t.slug === slug) ?? null;

export const allTraineeSlugs = () => data.trainees.map((t) => t.slug);
